import kotlinx.coroutines.flow.*
import kotlin.test.assertEquals

interface Repo { suspend fun al(): String }

class VM(private val r: Repo) {
    private val _v = MutableStateFlow("bos")
    val v: StateFlow<String> = _v.asStateFlow()
    suspend fun yukle() { _v.value = r.al() }
}

fun main() = runBlocking {
    val saxta = object : Repo { override suspend fun al() = "test-data" }
    val vm = VM(saxta)
    vm.yukle()
    assertEquals("test-data", vm.v.value)
    println("kecdi")
}

